package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"

	"github.com/shopspring/decimal"
)

// use decimal to avoid unused import error
var _ = decimal.NewFromInt(0)

type DateRec struct { // 01 DATE-REC, 12 bytes
	DtId   string // PIC X(4) @0 len=4
	DtYyyy int64  // PIC 9(4) @4 len=4
	DtMm   int64  // PIC 9(2) @8 len=2
	DtDd   int64  // PIC 9(2) @10 len=2
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string // PIC X len=1 = "N"
var WsLeapFlag string // PIC X len=1 = "N"
var WsQ int64 // PIC 9(4) len=4 = 0
var WsR4 int64 // PIC 9(3) len=3 = 0
var WsR100 int64 // PIC 9(3) len=3 = 0
var WsR400 int64 // PIC 9(3) len=3 = 0
var WsMaxDay int64 // PIC 99 len=2 = 0
var WsValid int64 // PIC 99 len=2 = 0
var WsBadMonth int64 // PIC 99 len=2 = 0
var WsBadDay int64 // PIC 99 len=2 = 0

var dtRec DateRec
var lines []string
var lineIdx int

func formatNumeric(v int64, digits int) string {
	mod := int64(1)
	for i := 0; i < digits; i++ {
		mod *= 10
	}
	// keep low-order digits (for positive values)
	if mod != 0 {
		v = v % mod
		if v < 0 {
			v = -v
			v = v % mod
		}
	}
	return fmt.Sprintf("%0*d", digits, v)
}

func parseNum(s string, digits int) int64 {
	trim := strings.TrimSpace(s)
	if trim == "" {
		return 0
	}
	// Try direct parse
	v, err := strconv.ParseInt(trim, 10, 64)
	if err != nil {
		// filter digits only
		var b strings.Builder
		for _, ch := range s {
			if ch >= '0' && ch <= '9' {
				b.WriteRune(ch)
			}
		}
		if b.Len() == 0 {
			return 0
		}
		v, _ = strconv.ParseInt(b.String(), 10, 64)
	}
	mod := int64(1)
	for i := 0; i < digits; i++ {
		mod *= 10
	}
	if mod != 0 {
		v = v % mod
		if v < 0 {
			v = -v
		}
	}
	return v
}

func ReadPara() {
	if lineIdx >= len(lines) {
		WsEofFlag = "Y"
		return
	}
	line := lines[lineIdx]
	lineIdx++
	if len(line) < 12 {
		line = line + strings.Repeat(" ", 12-len(line))
	} else if len(line) > 12 {
		line = line[:12]
	}
	dtRec.DtId = line[0:4]
	dtRec.DtYyyy = parseNum(line[4:8], 4)
	dtRec.DtMm = parseNum(line[8:10], 2)
	dtRec.DtDd = parseNum(line[10:12], 2)
}

func LeapPara() {
	// DIVIDE DT-YYYY BY 4 GIVING WS-Q REMAINDER WS-R4
	if 4 != 0 {
		WsQ = dtRec.DtYyyy / 4
		WsR4 = dtRec.DtYyyy % 4
		WsQ = WsQ % 10000
		WsR4 = WsR4 % 1000
	}
	if 100 != 0 {
		WsQ = dtRec.DtYyyy / 100
		WsR100 = dtRec.DtYyyy % 100
		WsQ = WsQ % 10000
		WsR100 = WsR100 % 1000
	}
	if 400 != 0 {
		WsQ = dtRec.DtYyyy / 400
		WsR400 = dtRec.DtYyyy % 400
		WsQ = WsQ % 10000
		WsR400 = WsR400 % 1000
	}
	if WsR4 == 0 && (WsR100 != 0 || WsR400 == 0) {
		WsLeapFlag = "Y"
	} else {
		WsLeapFlag = "N"
	}
}

func DaysPara() {
	switch dtRec.DtMm {
	case 2:
		if WsLeapFlag == "Y" {
			WsMaxDay = 29
		} else {
			WsMaxDay = 28
		}
	case 4, 6, 9, 11:
		WsMaxDay = 30
	default:
		WsMaxDay = 31
	}
	WsMaxDay = WsMaxDay % 100
}

func ProcessPara() {
	LeapPara()
	if dtRec.DtMm < 1 || dtRec.DtMm > 12 {
		WsBadMonth = (WsBadMonth + 1) % 100
		out := dtRec.DtId + " BAD MONTH " + formatNumeric(dtRec.DtMm, 2)
		fmt.Fprintln(os.Stdout, out)
	} else {
		DaysPara()
		if dtRec.DtDd < 1 || dtRec.DtDd > WsMaxDay {
			WsBadDay = (WsBadDay + 1) % 100
			out := dtRec.DtId + " BAD DAY " + formatNumeric(dtRec.DtDd, 2) + " MAX " + formatNumeric(WsMaxDay, 2)
			fmt.Fprintln(os.Stdout, out)
		} else {
			WsValid = (WsValid + 1) % 100
			out := dtRec.DtId + " VALID " + formatNumeric(dtRec.DtYyyy, 4) + "-" + formatNumeric(dtRec.DtMm, 2) + "-" + formatNumeric(dtRec.DtDd, 2)
			fmt.Fprintln(os.Stdout, out)
		}
	}
	ReadPara()
}

func MainPara() {
	f, err := os.Open("input.dat")
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	defer f.Close()
	scanner := bufio.NewScanner(f)
	// allow long lines
	const maxCapacity = 1024 * 1024
	buf := make([]byte, 0, 64*1024)
	scanner.Buffer(buf, maxCapacity)
	lines = []string{}
	for scanner.Scan() {
		lines = append(lines, scanner.Text())
	}
	if err := scanner.Err(); err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	ReadPara()
	for WsEofFlag != "Y" {
		ProcessPara()
	}
	// CLOSE DATE-FILE (implicit)
	out := "VALID: " + formatNumeric(WsValid, 2) + " BAD MONTH: " + formatNumeric(WsBadMonth, 2) + " BAD DAY: " + formatNumeric(WsBadDay, 2)
	fmt.Fprintln(os.Stdout, out)
}

func main() {
	WsEofFlag = "N"
	WsLeapFlag = "N"
	WsQ = 0
	WsR4 = 0
	WsR100 = 0
	WsR400 = 0
	WsMaxDay = 0
	WsValid = 0
	WsBadMonth = 0
	WsBadDay = 0
	MainPara()
}
